#!/usr/bin/env bash PROJECT\_ID=$(gcloud config get-value project) echo "====================================================" echo "🛡️ GCP SECURITY AUDIT REPORT: ${PROJECT\_ID}" echo "====================================================" echo "" echo "🔍 1\. Auditing IAM Roles (BYOSA Check)..." gcloud projects get-iam-policy "${PROJECT\_ID}" \\ --flatten="bindings[].members" \\ --format="table(bindings.role, bindings.members)" \\ | grep -E "roles/owner|roles/editor" || echo "✅ No overly broad primitive roles (Owner/Editor) assigned." echo "" echo "🔍 2\. Auditing Cloud Storage Bucket Access..." gcloud storage buckets list --format="value(name)" | while read -r bucket; do echo "Checking bucket: gs://${bucket}" gcloud storage buckets describe "gs://${bucket}" \\ --format="yaml(publicAccessPrevention, iamConfiguration.uniformBucketLevelAccess.enabled)" 2&gt;/dev/null done echo "" echo "🔍 3\. Verifying Cloud Run Backend Services..." gcloud run services list --platform=managed --format="table(name, region, serviceAccount, status.url)" echo "" echo "====================================================" echo "✅ AUDIT COMPLETE" echo "===================================================="
